export const CREATURE_NAMES = CREATURES.map((c) => c.name);
export function creatureByName(name) {
  const n = String(name || '').toLowerCase();
  return CREATURES.find((c) => c.name.de.toLowerCase() === n || c.name.en.toLowerCase() === n) || null;
}
